import {challenge as C} from './shared.js';
export default [
C(12,2,'审查续训存档是否具备必要字段',{
 goal:'根据明确的恢复契约列出缺失字段。',signature:'missing_resume_fields(checkpoint, recurrent)',contract:'基础必需字段为 model、optimizer、scheduler、step、rng、data_position；recurrent=True 还需 memory。缺失或值为 None 算缺失，0、False 和空字典算存在。返回按字母排序的字段列表。',context:'模型权重足以进行某些推理，但不一定能沿原训练过程续训。优化器状态、学习率日程、随机状态和数据位置都会影响下一次更新。字段齐全只是第一道审查，仍需验证恢复代码确实读取且语义正确。',steps:['建立所需字段集合，根据 recurrent 增加 memory。','逐字段检查是否不存在或值为 None。','排序返回，让审查报告稳定、可比较。'],worked:['step=0 是合法训练起点，不代表字段缺失。','optimizer={} 表示字段存在，但内容是否完整还需要后续语义校验。','本题不因字段存在就宣称实现了精确续训。'],mistake:'if not checkpoint.get(key) 会把合法的 0 和空容器一起误判。',transfer:'接着做连续训练与中断恢复的对照，才能检验实际恢复效果；课程下载脚本的能力以其实现为准。',cases:[['missing_resume_fields({"model":{},"optimizer":{},"scheduler":{},"step":0,"rng":{},"data_position":0},False)','[]','零与空容器算存在'],['missing_resume_fields({},True)','["data_position","memory","model","optimizer","rng","scheduler","step"]','完整缺失报告'],['missing_resume_fields({"model":1,"optimizer":1,"scheduler":1,"step":1,"rng":None,"data_position":1},False)','["rng"]','None 表示未保存']],solution:'def missing_resume_fields(checkpoint,recurrent):\n    required={"model","optimizer","scheduler","step","rng","data_position"}\n    if recurrent: required.add("memory")\n    return sorted(k for k in required if k not in checkpoint or checkpoint[k] is None)\n',quiz:['字段都存在，就证明精确恢复了吗？',['是','否，还要检查内容、加载路径和运行对照','只要有 model 就够'],1,'存在性检查是必要检查之一，不是运行等价性的证明。']
}),
C(12,4,'明确可比实验的边界',{
 goal:'找出两份报告中影响比较公平性的协议差异。',signature:'protocol_differences(left, right)',contract:'检查 data_version、split、metric、horizon、budget 五个键。任一侧缺失或值不同就返回该键；结果按字母排序。缺失不能视为两侧一致。',context:'算法面试中“提升了几个点”常会被追问基线、数据和预算。协议差异不自动证明实验无用，但会限制你能作出的结论。本题让未知项显式出现，防止把两份缺字段的报告误判为可比。',steps:['固定需要审查的五个键。','分别检查两侧是否存在该键，不能仅比较 get 默认值。','记录不同或缺失字段，返回排序列表。'],worked:['两侧 metric 相同但 horizon 分别为 1 与 20。','它们评估了不同的预测长度，不能只按数值排优劣。','即使两侧都没有 budget，也应列为需要补证据的字段。'],mistake:'缺失值彼此相等不等于实验条件相同。',transfer:'真实比较可能需要更多条件，且“同计算量”与“同训练步数”属于不同公平性定义，应在报告中写清。',cases:[['protocol_differences({"data_version":1,"split":"v","metric":"mse","horizon":1,"budget":10},{"data_version":1,"split":"v","metric":"mse","horizon":20,"budget":10})','["horizon"]','不同预测长度'],['protocol_differences({},{})','["budget","data_version","horizon","metric","split"]','缺失不是相同'],['protocol_differences({"data_version":1,"split":"v","metric":"mse","horizon":1,"budget":10},{"data_version":1,"split":"v","metric":"mse","horizon":1,"budget":10})','[]','字段一致']],solution:'def protocol_differences(left,right):\n    keys=["data_version","split","metric","horizon","budget"]\n    return sorted(k for k in keys if k not in left or k not in right or left[k]!=right[k])\n',quiz:['两侧都没记录数据版本，可以视为数据相同吗？',['可以','不可以，需要补证据','只要模型同名就可以'],1,'缺少证据不能自动补成相等的条件。']
}),
C(12,6,'仅用验证集选择候选模型',{
 goal:'按验证指标选择 checkpoint，防止偷用测试集挑选。',signature:'select_checkpoint(runs)',contract:'runs 为非空字典列表，每项含 id、validation_mse、test_mse。返回 validation_mse 最小的 id，并列按 id 字符串字典序选择。test_mse 不得参与选择。',context:'测试集应帮助评价最终选择，而不是反复参与选择。一旦用测试成绩挑模型，就把它变成了验证集。本题故意给出 test_mse，检查你能否守住评测流程的边界。',steps:['构造只包含 validation_mse 与 id 的排序键。','选择最小值，不访问 test_mse 决定结果。','改变测试数值时，选择结果应保持不变。'],worked:['A 的验证误差 1、测试误差 9；B 的验证误差 2、测试误差 0。','按已约定流程应该选 A。','之后 A 的差测试表现需要报告，不能倒过来用 B 掩盖这个事实。'],mistake:'同时使用验证与测试均值选择模型，会污染独立测试。',transfer:'在最终报告中保留选型规则、全部候选与最终独立评测；不要只展示最佳测试运行。',cases:[['select_checkpoint([{"id":"A","validation_mse":1,"test_mse":9},{"id":"B","validation_mse":2,"test_mse":0}])','"A"','测试好不改变选型'],['select_checkpoint([{"id":"b","validation_mse":1,"test_mse":0},{"id":"a","validation_mse":1,"test_mse":9}])','"a"','并列规则'],['select_checkpoint([{"id":"only","validation_mse":3,"test_mse":4}])','"only"','单候选']],solution:'def select_checkpoint(runs):\n    return min(runs,key=lambda r:(r["validation_mse"],r["id"]))["id"]\n',quiz:['反复根据测试集挑配置后，它实际上承担了什么角色？',['仍是完全独立测试','参与了模型选择，类似验证集','训练输入张量'],1,'数据集合的角色由实际使用方式决定。']
}),
C(12,7,'最终项目：训练、rollout 与基线报告',{
 goal:'训练双参数动态模型，用独立轨迹比较模型与保持不动基线。',signature:'world_model_report(train, initial, actions, targets, steps, lr)',contract:'train 为非空 (s,a,next_s) 标量三元组；模型 next=w*s+u*a，w=u=0，按平均平方损失全批量更新 steps 次。actions、targets 等长非空。返回 state_weight、action_weight、rollout_mse、persistence_mse 四键字典。保持不动基线每步预测 initial。',context:'这次要同时解释结构、数据、目标、更新和评测。与第八周不同，状态本身的系数也可学习。综合项目不是完整转岗证明，而是一份能被自动核对的最小作品；真实项目还应增加非线性状态、图像表示、数据版本与重复实验。',steps:['使用旧 w、u 计算所有训练误差，分别求平均 2*error*s 与 2*error*a。','同时更新两个参数，验证 targets 不得参与这个循环。','从 initial 自由运行，记录对 targets 的 MSE；另计算固定 initial 的基线 MSE，使用相同分母。'],worked:['train=[(1,0,2),(0,1,3)]，steps=1、lr=1。','初始梯度分别为 -2、-3，所以 w=2、u=3。','initial=1、actions=[1,0]，预测 [5,10]；目标同为 [5,10]，模型误差为零，保持不动基线误差为 48.5。'],mistake:'如果训练过程中混入 targets，或 rollout 每步读取真实状态，报告就不再符合题目定义。',transfer:'完成后把数据卡、代码、运行命令和失败样例一起整理，再将同一审查顺序应用到 OmniFM。通过玩具任务是起点，不替代公司规模训练经验。',cases:[['world_model_report([(1,0,2),(0,1,3)],1,[1,0],[5,10],1,1)','{"state_weight":2,"action_weight":3,"rollout_mse":0,"persistence_mse":48.5}','完整学习与评测'],['world_model_report([(1,0,2)],1,[1],[2],0,0.1)','{"state_weight":0,"action_weight":0,"rollout_mse":4,"persistence_mse":1}','未训练模型可能输基线'],['world_model_report([(1,0,1),(0,1,1)],0,[1,1],[1,2],1,1)','{"state_weight":1,"action_weight":1,"rollout_mse":0,"persistence_mse":2.5}','另一种动态']],extraTests:[{name:'验证目标不影响学到的参数',code:'a=world_model_report([(1,0,2),(0,1,3)],1,[1],[5],5,0.1)\nb=world_model_report([(1,0,2),(0,1,3)],1,[1],[999],5,0.1)\nassert a["state_weight"]==b["state_weight"] and a["action_weight"]==b["action_weight"]'}],solution:'def world_model_report(train,initial,actions,targets,steps,lr):\n    w=u=0.0\n    for _ in range(steps):\n        errors=[w*s+u*a-y for s,a,y in train]\n        dw=sum(2*e*s for e,(s,a,y) in zip(errors,train))/len(train)\n        du=sum(2*e*a for e,(s,a,y) in zip(errors,train))/len(train)\n        w,u=w-lr*dw,u-lr*du\n    state=initial; errors=[]\n    for a,y in zip(actions,targets):\n        state=w*state+u*a; errors.append((state-y)**2)\n    return {"state_weight":w,"action_weight":u,"rollout_mse":sum(errors)/len(errors),"persistence_mse":sum((initial-y)**2 for y in targets)/len(targets)}\n',quiz:['最终模型比保持不动基线差，应如何处理？',['隐去基线','保留结果并检查数据、训练与协议','只报告训练 loss'],1,'负结果也是诊断证据，不能用挑指标替代问题定位。']
})];
